const StorePaymentForm = ({ listing, email, isPhysical, onBack, onComplete }: StorePaymentFormProps) => {
  const checkoutState = useCheckout();
  const [paymentError, setPaymentError] = useState('');
  const [confirming, setConfirming] = useState(false);
  const [promotionOpen, setPromotionOpen] = useState(false);
  const [promotionCode, setPromotionCode] = useState('');
  const [promotionLoading, setPromotionLoading] = useState(false);
  const [expressCheckoutAvailable, setExpressCheckoutAvailable] = useState<boolean | null>(null);

  if (checkoutState.type === 'loading') {
    return (
      <div className="flex min-h-[420px] flex-col items-center justify-center rounded-[2rem] border border-white/10 bg-[#111] text-center">
        <Loader2 className="h-8 w-8 animate-spin text-white" />
        <p className="mt-4 text-sm font-bold text-white/60">Preparing secure payment methods…</p>
      </div>
    );
  }

  if (checkoutState.type === 'error') {
    return (
      <div role="alert" className="rounded-[2rem] border border-red-400/20 bg-red-400/10 p-6 text-red-100">
        <p className="font-black">Secure payment could not load</p>
        <p className="mt-2 text-sm text-red-100/70">{checkoutState.error.message}</p>
        <button type="button" onClick={onBack} className="mt-5 rounded-full border border-red-100/20 px-5 py-2.5 text-sm font-bold">Back to details</button>
      </div>
    );
  }

  const { checkout } = checkoutState;
  const total = checkout.total.total.amount;
  const hasPromotion = Boolean(checkout.discountAmounts?.length);

  const confirmPayment = async (expressCheckoutConfirmEvent?: any) => {
    setPaymentError('');
    setConfirming(true);
    try {
      const result = await checkout.confirm({
        redirect: 'if_required',
        email,
        ...(expressCheckoutConfirmEvent ? { expressCheckoutConfirmEvent } : {}),
      });
      if (result.type === 'error') {
        setPaymentError(result.error.message || 'Payment could not be completed.');
        return;
      }
      onComplete(result.session.id);
    } catch (error) {
      console.error('Custom checkout confirmation failed:', error);
      setPaymentError('Secure payment could not be completed. Please try again.');
    } finally {
      setConfirming(false);
    }
  };

  const applyPromotionCode = async () => {
    const code = promotionCode.trim();
    if (!code) return;
    setPromotionLoading(true);
    setPaymentError('');
    try {
      const result = await checkout.applyPromotionCode(code);
      if (result.type === 'error') {
        setPaymentError(result.error.message || 'This promotion code could not be applied.');
        return;
      }
      setPromotionCode('');
      setPromotionOpen(false);
    } finally {
      setPromotionLoading(false);
    }
  };

  const removePromotionCode = async () => {
    setPromotionLoading(true);
    setPaymentError('');
    try {
      const result = await checkout.removePromotionCode();
      if (result.type === 'error') setPaymentError(result.error.message || 'The promotion code could not be removed.');
    } finally {
      setPromotionLoading(false);
    }
  };

  return (
    <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_320px]">
      <div className="min-w-0 space-y-5">
        <section className="overflow-hidden rounded-[2rem] border border-white/10 bg-[#111] p-5 sm:p-7">
          <div className="mb-6">
            <p className="text-[10px] font-black uppercase tracking-[0.24em] text-indigo-300">Fast checkout</p>
            <h2 className="mt-2 text-2xl font-black tracking-tight sm:text-3xl">Choose how you pay</h2>
            <p className="mt-2 text-sm leading-6 text-white/50">Select a wallet or enter your preferred payment details below.</p>
          </div>

          <div className={expressCheckoutAvailable === false ? 'hidden' : undefined}>
            <ExpressCheckoutElement
              onReady={(event) => {
                const methods = event.availablePaymentMethods;
                setExpressCheckoutAvailable(Boolean(methods && Object.values(methods).some(Boolean)));
              }}
              onLoadError={() => setExpressCheckoutAvailable(false)}
              onConfirm={event => void confirmPayment(event)}
              options={{
                buttonHeight: 52,
                buttonTheme: undefined,
                buttonType: undefined,
                layout: { maxColumns: 2, maxRows: 2, overflow: 'auto' },
                paymentMethodOrder: undefined,
                paymentMethods: undefined,
              }}
            />
          </div>

          {expressCheckoutAvailable !== false && (
            <div className="my-6 flex items-center gap-3 text-[10px] font-black uppercase tracking-[0.18em] text-white/30">
              <span className="h-px flex-1 bg-white/10" />
              Or use another method
              <span className="h-px flex-1 bg-white/10" />
            </div>
          )}

          {isPhysical && (
            <div className="mb-6 rounded-2xl border border-white/10 bg-black/30 p-4">
              <p className="mb-4 text-sm font-black">Delivery address</p>
              <ShippingAddressElement />
            </div>
          )}

          <div className="rounded-2xl border border-white/10 bg-black/30 p-4">
            <PaymentElement options={{ layout: 'accordion' }} />
          </div>
        </section>

        <section className="rounded-[2rem] border border-white/10 bg-[#111] p-5 sm:p-6">
          <button
            type="button"
            onClick={() => setPromotionOpen(open => !open)}
            className="flex w-full items-center justify-between gap-3 text-left"
            aria-expanded={promotionOpen}
          >
            <span className="flex items-center gap-3 text-sm font-black"><Tag className="h-4 w-4 text-indigo-300" /> Promotion code</span>
            <span className="text-xs font-bold text-white/45">{hasPromotion ? 'Applied' : promotionOpen ? 'Close' : 'Add code'}</span>
          </button>

          {hasPromotion ? (
            <div className="mt-4 flex items-center justify-between rounded-xl border border-emerald-400/20 bg-emerald-400/10 px-4 py-3 text-sm">
              <span className="font-bold text-emerald-200">Discount applied</span>
              <button type="button" onClick={() => void removePromotionCode()} disabled={promotionLoading} aria-label="Remove promotion code" className="rounded-full p-1 text-emerald-100/70 hover:bg-white/10 hover:text-white disabled:opacity-40"><X className="h-4 w-4" /></button>
            </div>
          ) : promotionOpen ? (
            <div className="mt-4 flex flex-col gap-2 sm:flex-row">
              <input
                value={promotionCode}
                onChange={event => setPromotionCode(event.target.value)}
                onKeyDown={event => { if (event.key === 'Enter') void applyPromotionCode(); }}
                placeholder="Enter your code"
                autoComplete="off"
                className="min-h-12 flex-1 rounded-xl border border-white/10 bg-black/30 px-4 text-sm font-bold uppercase tracking-wide outline-none focus:border-indigo-300"
              />
              <button type="button" onClick={() => void applyPromotionCode()} disabled={!promotionCode.trim() || promotionLoading} className="min-h-12 rounded-xl bg-white px-5 text-sm font-black text-black disabled:opacity-40">
                {promotionLoading ? <Loader2 className="mx-auto h-4 w-4 animate-spin" /> : 'Apply'}
              </button>
            </div>
          ) : null}
        </section>

        {paymentError && (
          <div role="alert" className="flex items-start gap-3 rounded-2xl border border-red-400/20 bg-red-400/10 p-4 text-sm text-red-100">
            <AlertCircle className="mt-0.5 h-5 w-5 shrink-0 text-red-300" />
            <div><p className="font-black">Payment needs attention</p><p className="mt-1 text-red-100/70">{paymentError}</p></div>
          </div>
        )}
      </div>

      <aside className="lg:sticky lg:top-28">
        <div className="overflow-hidden rounded-[2rem] border border-white/10 bg-[#111]">
          <div className="border-b border-white/10 p-5">
            <p className="text-[10px] font-black uppercase tracking-[0.22em] text-white/35">Order summary</p>
            <div className="mt-4 flex items-center gap-3">
              <div className="h-14 w-14 shrink-0 overflow-hidden rounded-2xl bg-white/5">
                {listing.images?.[0] ? <img src={listing.images[0]} alt="" className="h-full w-full object-cover" referrerPolicy="no-referrer" /> : <span className="flex h-full w-full items-center justify-center"><ShoppingBag className="h-5 w-5 text-white/30" /></span>}
              </div>
              <div className="min-w-0"><p className="truncate text-sm font-black">{listing.title}</p><p className="mt-1 truncate text-xs text-white/40">Receipt to {email}</p></div>
            </div>
          </div>
          <div className="space-y-3 p-5 text-sm">
            {checkout.lineItems.map(item => (
              <div key={item.id} className="flex items-start justify-between gap-4 text-white/55"><span className="min-w-0 truncate">{item.name}</span><span className="shrink-0 font-mono text-white/80">{item.total.amount}</span></div>
            ))}
            {hasPromotion && <div className="flex items-center justify-between text-emerald-300"><span>Promotion</span><span className="font-bold">Applied</span></div>}
            <div className="flex items-end justify-between border-t border-white/10 pt-4"><span className="text-xs font-black uppercase tracking-wider text-white/40">Total</span><span className="font-mono text-2xl font-black">{total}</span></div>
          </div>
          <div className="space-y-3 border-t border-white/10 p-5">
            <button
              type="button"
              onClick={() => void confirmPayment()}
              disabled={!checkout.canConfirm || confirming}
              className="flex min-h-14 w-full items-center justify-center gap-2 rounded-full bg-white px-5 text-sm font-black text-black transition hover:bg-indigo-100 disabled:cursor-not-allowed disabled:opacity-40"
            >
              {confirming ? <Loader2 className="h-5 w-5 animate-spin" /> : <><Lock className="h-4 w-4" /> Pay {total}</>}
            </button>
            <button type="button" onClick={onBack} disabled={confirming} className="flex w-full items-center justify-center gap-1 py-2 text-xs font-bold text-white/45 hover:text-white disabled:opacity-40"><ChevronLeft className="h-4 w-4" /> Back to details</button>
            <div className="flex items-center justify-center gap-2 pt-1 text-[10px] font-bold uppercase tracking-wider text-white/30"><ShieldCheck className="h-4 w-4" /> Encrypted by Stripe</div>
          </div>
        </div>
      </aside>
    </div>
  );
};

export const Checkout = ({ presentation = 'page' }: CheckoutProps) => {
  const { id } = useParams();
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const { locale, currency } = useLocale();
  const { items: cartItems, removeItem } = useCart();
  
  const [listing, setListing] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [email, setEmail] = useState('');
  
  const [step, setStep] = useState(1);
  const [selectedPlan, setSelectedPlan] = useState<number | null>(null);
  const [clientSecret, setClientSecret] = useState<string | null>(null);
  const [orderId, setOrderId] = useState<string | null>(null);
  const [paymentError, setPaymentError] = useState('');
  const [stripePromise, setStripePromise] = useState<Promise<Stripe | null> | null>(initialStripePromise);
  const [stripeKeyUnavailable, setStripeKeyUnavailable] = useState(false);
  const [stripeConfigLoading, setStripeConfigLoading] = useState(false);
  const [selected3DLicense, setSelected3DLicense] = useState<any>(null);
  const [sellerTrace, setSellerTrace] = useState<any>(null);
  const [paymentReadiness, setPaymentReadiness] = useState<'checking' | 'ready' | 'unavailable'>('checking');
  const [immediateDeliveryRequested, setImmediateDeliveryRequested] = useState(false);
  const [withdrawalEffectAcknowledged, setWithdrawalEffectAcknowledged] = useState(false);
  const [complianceDecision, setComplianceDecision] = useState<ComplianceDecision | null>(null);
  const [paymentResult, setPaymentResult] = useState<CheckoutPaymentResult | null>(null);
  const checkoutIdempotencyKey = useRef(crypto.randomUUID());
  const stripeLoadPromiseRef = useRef<Promise<boolean> | null>(null);

  const planIdxParam = searchParams.get('plan');
  const licenseParam = searchParams.get('license');
  const isSheet = presentation === 'sheet';
  const reduceMotion = useReducedMotion();
  const closeCheckout = () => navigate(-1);

  useEffect(() => {
    if (!isSheet) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') closeCheckout();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isSheet]);
  
  useEffect(() => {
    if (planIdxParam !== null) {
      setSelectedPlan(parseInt(planIdxParam));
    }
  }, [planIdxParam]);

  useEffect(() => {
    if (user?.email) {
      setEmail(user.email);
    }
  }, [user]);

  const loadCheckoutStripe = async () => {
    if (stripePromise) return true;
    if (stripeLoadPromiseRef.current) return stripeLoadPromiseRef.current;

    const loadTask = (async () => {
      setStripeConfigLoading(true);
      try {
        const config = await invokeApiRunner('stripe-config', {}, 1, 500);
        const publishableKey = typeof config?.publishableKey === 'string' ? config.publishableKey.trim() : '';

        if (!publishableKey) {
          setStripeKeyUnavailable(true);
          return false;
        }

        const loadedStripe = await loadStripe(publishableKey);
        if (!loadedStripe) {
          setStripeKeyUnavailable(true);
          return false;
        }

        setStripeKeyUnavailable(false);
        setStripePromise(Promise.resolve(loadedStripe));
        return true;
      } catch {
        setStripeKeyUnavailable(true);
        return false;
      } finally {
        setStripeConfigLoading(false);
      }
    })();

    stripeLoadPromiseRef.current = loadTask;
    try {
      return await loadTask;
    } finally {
      stripeLoadPromiseRef.current = null;
    }
  };

  useEffect(() => {
    if (!stripePromise) {
      void loadCheckoutStripe();
    } else {
      setStripeConfigLoading(false);
      setStripeKeyUnavailable(false);
    }
  }, [stripePromise]);

  useEffect(() => {
    const fetchListing = async () => {
      try {
        const { data, error } = await supabase
          .from('listings')
          .select('id,seller_id,title,description,price,type,status,images,image_url,thumbnail,metadata,plans,pricing_type,billing_interval,base_currency,is_sandbox,deleted_at,published_at,product_offers(*),profiles!listings_seller_id_fkey(username,full_name,avatar_url)')
          .eq('id', id)
          .eq('status', 'published')
          .eq('is_sandbox', false)
          .is('deleted_at', null)
          .maybeSingle();
        if (error) throw error;

        const normalizedData = data
          ? {
              ...data,
              metadata: parseMarketplaceMetadata(data.metadata),
              images: parseMarketplaceImages(data.images).length > 0
                ? parseMarketplaceImages(data.images)
                : parseMarketplaceImages(data.image_url || data.thumbnail),
            }
          : null;
        setListing(normalizedData);

        if (normalizedData?.seller_id) {
          const { data: trace } = await supabase
            .from('dsa_seller_verifications')
            .select('trader_status,country_code,status')
            .eq('seller_id', normalizedData.seller_id)
            .maybeSingle();
          setSellerTrace(trace);
        }

        if (normalizedData?.type === 'asset_3d' && licenseParam) {
          const { data: licenseData, error: licenseError } = await supabase
            .from('product_3d_licenses')
            .select('*, product_3d_license_prices(*)')
            .eq('id', licenseParam)
            .eq('listing_id', id)
            .eq('active', true)
            .maybeSingle();
          if (licenseError) throw licenseError;
          setSelected3DLicense(licenseData);
        }
        
        if (normalizedData?.plans?.length > 0 && selectedPlan === null) {
          setSelectedPlan(0); // Default to first plan if plans exist
        }
      } catch (err) {
        console.error('Error fetching checkout data:', err);
      } finally {
        setLoading(false);
      }
    };

    if (id) {
      fetchListing();
    } else {
      setLoading(false);
    }
  }, [id, licenseParam]);

  useEffect(() => {
    if (!listing?.id) {
      setPaymentReadiness('unavailable');
      return;
    }
    const selectedPlanPrice = selectedPlan !== null && listing.plans?.[selectedPlan]
      ? listing.plans[selectedPlan].price
      : undefined;
    const rawPrice = selectedPlanPrice ?? resolveProductPricing(listing).currentPrice;
    if (Number(rawPrice) === 0) {
      setPaymentReadiness('ready');
      return;
    }

    let active = true;
    setPaymentReadiness('checking');
    void trustCenterAction<{
      success: true;
      available: boolean;
      paymentRequired?: boolean;
      reason?: string | null;
    }>('checkout-readiness', { listingId: listing.id, planIndex: selectedPlan })
      .then((readiness) => {
        if (active) setPaymentReadiness(readiness.available ? 'ready' : 'unavailable');
      })
      .catch(() => {
        if (active) setPaymentReadiness('unavailable');
      });
    return () => {
      active = false;
    };
  }, [listing, selectedPlan]);

  const getPrice = (): number | null => {
    let rawPrice: unknown;
    if (selectedPlan !== null && listing?.plans?.[selectedPlan]) {
      rawPrice = listing.plans[selectedPlan].price;
    } else if (listing?.type === 'asset_3d' && selected3DLicense?.product_3d_license_prices?.[0]) {
      const licensePrice = selected3DLicense.product_3d_license_prices[0];
      const minorPrice = licensePrice.sale_price_minor ?? licensePrice.price_minor;
      rawPrice = minorPrice === null || minorPrice === undefined ? null : Number(minorPrice) / 100;
    } else {
      if (listing?.price === null || listing?.price === undefined || listing?.price === '') return null;
      rawPrice = resolveProductPricing(listing).currentPrice;
    }
    const numericPrice = Number(rawPrice);
    return Number.isFinite(numericPrice) && numericPrice >= 0 ? numericPrice : null;
  };

  const getBaseCurrency = () => {
    if (selectedPlan !== null && listing?.plans?.[selectedPlan]) {
      return (listing.plans[selectedPlan].currency || listing.currency || listing.base_currency || 'EUR').toUpperCase();
    }
    if (listing?.type === 'asset_3d' && selected3DLicense?.product_3d_license_prices?.[0]) {
      return (selected3DLicense.product_3d_license_prices[0].currency || listing.currency || listing.base_currency || 'EUR').toUpperCase();
    }
    return (listing?.currency || listing?.base_currency || 'EUR').toUpperCase();
  };

  const planName = selectedPlan !== null ? listing?.plans?.[selectedPlan]?.name : null;
  const price = getPrice();
  const priceAvailable = price !== null;
  const baseCurrency = getBaseCurrency();
  const checkoutPricing = resolveProductPricing(listing);
  const isFree = price === 0;
  const isDigitalProduct = ['digital', 'course', 'software', 'asset_3d', 'music', 'beat', 'template', 'virtual', 'community'].includes(String(listing?.type || '').toLowerCase());
  const isPhysicalProduct = ['physical', 'product', 'pos', 'pos_item'].includes(String(listing?.type || '').toLowerCase());
  const isSubscription = Boolean(listing?.pricing_type === 'subscription' || listing?.billing_interval || listing?.metadata?.subscription_interval);

  const showConfirmation = (view: PaymentView, reference: string | null, verifying = false) => {
    setPaymentResult({ view, reference, verifying });
    setStep(4);
  };

  const handlePaymentComplete = async (sessionId: string) => {
    showConfirmation('processing', sessionId, true);
    try {
      const result = await trustCenterAction<{
        success: true;
        status: PaymentView;
        orderId?: string | null;
      }>('checkout-status', { sessionId });
      setPaymentResult({
        view: normalizePaymentView(result.status) || 'error',
        reference: result.orderId || orderId || sessionId,
        verifying: false,
      });
    } catch (error) {
      console.warn('Product payment status verification was unavailable', error);
      setPaymentResult({ view: 'error', reference: sessionId, verifying: false });
    }
  };

  const handleContinueToPayment = async () => {
    setPaymentError('');
    if (!email && !user) {
      toast.error('Please enter your email address.');
      return;
    }
    if (!user && !EMAIL_PATTERN.test(email.trim())) {
      toast.error('Please enter a valid email address.');
      return;
    }
    if (!priceAvailable) {
      const message = 'The seller has not provided a valid checkout price for this listing.';
      setPaymentError(message);
      toast.error(message);
      return;
    }

    if (!isFree && paymentReadiness !== 'ready') {
      const message = paymentReadiness === 'checking'
        ? 'Payment availability is still being checked.'
        : 'This seller cannot accept payments for this listing yet.';
      setPaymentError(message);
      toast.error(message);
      return;
    }

    if (!isFree && !stripePromise) {
      const stripeReady = await loadCheckoutStripe();
      if (!stripeReady) {
        const message = stripeKeyUnavailable
          ? 'Secure payments are temporarily unavailable. Please try again later.'
          : 'Secure checkout is still being prepared. Please try again.';
        setPaymentError(message);
        toast.error(message);
        return;
      }
    }

    setProcessing(true);
    try {
      void trackProductConversion(String(listing.id), 'checkout_started', 'checkout');
      trackMarketplaceEvent('checkout_started', { listingId: String(listing.id) });
      const resData = await trustCenterAction<{
        success: true;
        clientSecret?: string;
        free?: boolean;
        orderId?: string;
        uiMode?: 'custom' | 'embedded';
        decision: ComplianceDecision;
      }>('create-checkout', {
        listingId: listing.id,
        offerId: checkoutPricing.offer?.id,
        planIndex: selectedPlan,
        licenseId: selected3DLicense?.id || licenseParam || undefined,
        customerEmail: email || user?.email,
        anonymousId: getAnonymousConsentId(),
        countryCode: locale.split('-')[1] || undefined,
        preferredCurrency: currency,
        immediateDeliveryRequested,
        withdrawalEffectAcknowledged,
        idempotencyKey: checkoutIdempotencyKey.current,
        checkoutUiMode: 'custom',
        successUrl: `${window.location.origin}/payment-success?source=product&session_id={CHECKOUT_SESSION_ID}&listingId=${listing.id}&return_to=${encodeURIComponent(`/checkout/${listing.id}`)}`,
      });
      setComplianceDecision(resData.decision);

      if (resData.free && resData.orderId) {
        showConfirmation('success', resData.orderId);
        return;
      }

      if (resData.clientSecret && resData.uiMode === 'custom') {
        setClientSecret(resData.clientSecret);
        setOrderId(resData.orderId || null);
        setStep(3);
      } else {
        throw new Error('The custom payment session is not available yet');
      }
    } catch (err: any) {
      console.error('Payment error:', err);
      const code = String(err?.code || '').toUpperCase();
      const rawMessage = String(err?.message || '');
      const sellerNotReady = [
        'STRIPE_ONBOARDING_INCOMPLETE',
        'SELLER_PAYMENTS_DISABLED',
        'ACCOUNT_CHARGES_DISABLED',
        'STRIPE_ACCOUNT_INACCESSIBLE',
      ].includes(code) || /onboarding|charges.enabled|connected account|accept payments/i.test(rawMessage);
      const complianceDetails = err instanceof TrustCenterError && err.details && typeof err.details === 'object'
        ? err.details as ComplianceDecision
        : null;
      if (complianceDetails) setComplianceDecision(complianceDetails);
      const consentRequired = code === 'COMPLIANCE_BLOCKED' && isDigitalProduct && (!immediateDeliveryRequested || !withdrawalEffectAcknowledged);
      const message = consentRequired
        ? 'Confirm both digital-delivery choices before continuing.'
        : sellerNotReady
        ? 'This seller cannot accept payments yet. Their payment account still needs verification.'
        : rawMessage || 'Payment setup failed. Please try again.';
      setPaymentError(message);
      toast.error(message);
    } finally {
      setProcessing(false);
    }
  };

  if (loading) {
    if (isSheet) {
      return (
        <CheckoutSheetState label="Preparing secure checkout" onClose={closeCheckout}>
          <div className="flex min-h-72 flex-col items-center justify-center px-6 pb-[env(safe-area-inset-bottom)] text-center">
            <Loader2 className="h-8 w-8 animate-spin text-white" />
            <p className="mt-4 text-sm font-bold text-white/60">Preparing your secure checkout...</p>
          </div>
        </CheckoutSheetState>
      );
    }
    return <div className="min-h-[100dvh] flex items-center justify-center bg-black"><div className="w-8 h-8 border-4 border-white/20 border-t-white rounded-full animate-spin"></div></div>;
  }

  if (!id) {
    return (
      <div className="min-h-[100dvh] bg-[#060606] text-white">
        <header className="sticky top-0 z-50 px-4 py-4 sm:px-6">
          <div className="liquid-glass-pill mx-auto flex h-14 max-w-5xl items-center justify-between rounded-full px-3 sm:px-5">
            <button type="button" onClick={() => navigate(-1)} className="flex h-10 items-center gap-1 rounded-full px-3 text-sm font-bold text-white/70 transition hover:bg-white/10 hover:text-white">
              <ChevronLeft className="h-5 w-5" /> Back
            </button>
            <Link to="/" className="text-lg font-black italic tracking-tighter">WERSEE</Link>
            <LocaleCurrencyPicker className="justify-end" />
          </div>
        </header>

        <main className="mx-auto w-full max-w-5xl px-4 pb-20 pt-8 sm:px-6 sm:pt-12">
          <div className="mb-8 flex items-end justify-between gap-4">
            <div>
              <p className="mb-2 text-xs font-black uppercase tracking-[0.24em] text-blue-300">Your Wersee cart</p>
              <h1 className="text-4xl font-black tracking-tight sm:text-6xl">Ready when you are.</h1>
            </div>
            <div className="liquid-glass-pill hidden rounded-full px-5 py-3 text-sm font-bold text-white/70 sm:block">
              {cartItems.length} {cartItems.length === 1 ? 'item' : 'items'}
            </div>
          </div>

          {cartItems.length === 0 ? (
            <section className="liquid-glass-pill flex min-h-[420px] flex-col items-center justify-center rounded-[2rem] px-6 text-center">
              <div className="mb-6 flex h-20 w-20 items-center justify-center rounded-3xl border border-white/10 bg-white/[0.06]">
                <ShoppingBag className="h-9 w-9 text-white/55" />
              </div>
              <h2 className="text-2xl font-black">Your cart is empty</h2>
              <p className="mt-2 max-w-sm text-sm leading-6 text-white/50">Browse the storefront and add a product, course, service, or digital download to continue.</p>
              <button onClick={() => navigate('/')} className="mt-7 flex items-center gap-2 rounded-full bg-white px-7 py-3.5 text-sm font-black text-black transition hover:scale-[1.02] hover:bg-white/90">
                <Store className="h-4 w-4" /> Explore the store
              </button>
            </section>
          ) : (
            <div className="space-y-4">
              {cartItems.map((item) => {
                const checkoutPath = `/checkout/${item.listingId}${item.planIndex !== undefined ? `?plan=${item.planIndex}` : ''}`;
                return (
                  <article key={`${item.listingId}:${item.planIndex ?? ''}`} className="liquid-glass-pill grid gap-5 rounded-[2rem] p-4 sm:grid-cols-[112px_1fr_auto] sm:items-center sm:p-5">
                    <div className="aspect-square overflow-hidden rounded-2xl border border-white/10 bg-white/[0.05]">
                      {item.image ? <img src={item.image} alt="" className="h-full w-full object-cover" referrerPolicy="no-referrer" /> : <ShoppingBag className="m-auto h-full w-8 text-white/25" />}
                    </div>
                    <div className="min-w-0">
                      <p className="text-xs font-black uppercase tracking-[0.2em] text-white/35">{item.type.replace('_', ' ')}</p>
                      <h2 className="mt-1 truncate text-xl font-black sm:text-2xl">{item.title}</h2>
                      <LocalizedPrice amount={item.price} baseCurrency={item.currency} className="mt-3 block text-lg font-black text-white/80" showOriginal={false} />
                    </div>
                    <div className="flex items-center gap-2 sm:flex-col sm:items-stretch">
                      <button onClick={() => navigate(checkoutPath)} className="flex h-12 flex-1 items-center justify-center gap-2 rounded-full bg-white px-6 text-sm font-black text-black transition hover:bg-white/90">
                        Checkout <ArrowRight className="h-4 w-4" />
                      </button>
                      <button onClick={() => removeItem(item.listingId, item.planIndex)} className="flex h-12 w-12 items-center justify-center rounded-full border border-white/10 bg-white/[0.04] text-white/50 transition hover:bg-red-500/10 hover:text-red-300" aria-label={`Remove ${item.title} from cart`}>
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>
                  </article>
                );
              })}
            </div>
          )}
        </main>
      </div>
    );
  }

  if (!listing && !loading) {
    if (isSheet) {
      return (
        <CheckoutSheetState label="Listing unavailable" onClose={closeCheckout}>
          <div className="flex min-h-80 flex-col items-center justify-center px-6 pb-[calc(1.5rem+env(safe-area-inset-bottom))] text-center">
            <div className="flex h-16 w-16 items-center justify-center rounded-3xl border border-white/10 bg-white/[0.05]"><ShoppingBag className="h-7 w-7 text-white/35" /></div>
            <h1 className="mt-5 text-2xl font-black">This listing is unavailable</h1>
            <p className="mt-2 max-w-sm text-sm leading-6 text-white/50">It may have been removed, archived, or is not published for sale.</p>
            <button type="button" onClick={closeCheckout} className="mt-6 min-h-12 rounded-full bg-white px-7 text-sm font-black text-black">Return to the store</button>
          </div>
        </CheckoutSheetState>
      );
    }
    return (
      <div className="min-h-screen bg-[#0A0A0A] flex flex-col text-white">
        <header className="sticky top-0 z-50 grid grid-cols-[1fr_auto] items-center gap-x-3 gap-y-2 border-b border-white/10 bg-[#141414] px-4 py-3 sm:grid-cols-[1fr_auto_1fr] sm:px-6 sm:py-4">
          <button type="button" className="flex items-center gap-2 justify-self-start" onClick={() => navigate(-1)}>
            <ChevronLeft className="w-5 h-5 text-gray-400" />
            <span className="font-bold text-gray-300">Back</span>
          </button>
          <div className="justify-self-end text-xl font-black tracking-tighter text-white sm:justify-self-center">WERSEE</div>
          <LocaleCurrencyPicker className="col-span-2 w-full justify-end sm:col-span-1 sm:justify-self-end" />
        </header>
        <div className="flex-1 flex flex-col items-center justify-center px-4 text-center">
          <div className="w-20 h-20 bg-white/5 rounded-3xl flex items-center justify-center mb-6">
            <ShoppingBag className="w-10 h-10 text-gray-400" />
          </div>
          <h1 className="text-2xl font-bold text-white mb-2">This listing is unavailable</h1>
          <p className="max-w-md text-sm leading-6 text-white/55">It may have been removed, archived, or is not published for sale.</p>
          <button onClick={() => navigate('/search')} className="mt-6 px-8 py-3 bg-white text-black rounded-full font-bold hover:bg-gray-200 transition-all">
            Browse marketplace
          </button>
        </div>
      </div>
    );
  }

  const steps = [
    { id: 1, name: 'Order', icon: ShoppingBag },
    { id: 2, name: 'Details', icon: ReceiptText },
    { id: 3, name: 'Payment', icon: CreditCard },
    { id: 4, name: 'Confirmation', icon: CheckCircle2 },
  ];
  const confirmation = paymentResult ? confirmationCopy[paymentResult.view] : null;
  const ConfirmationIcon = confirmation?.icon || CheckCircle2;

  return (
    <div
      className={isSheet
        ? 'fixed inset-0 z-[200] flex items-end justify-center text-white'
        : 'min-h-screen bg-[#0A0A0A] flex flex-col text-white'}
    >
      {isSheet && (
        <motion.button
          type="button"
          aria-label="Close checkout"
          className="absolute inset-0 bg-black/70 backdrop-blur-md"
          initial={reduceMotion ? false : { opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={closeCheckout}
        />
      )}
      <motion.div
        initial={isSheet && !reduceMotion ? { y: '100%', opacity: 0.7 } : false}
        animate={{ y: 0, opacity: 1 }}
        exit={isSheet && !reduceMotion ? { y: '100%', opacity: 0.8 } : undefined}
        transition={isSheet ? (reduceMotion ? { duration: 0 } : { type: 'spring', stiffness: 360, damping: 38, mass: 0.9 }) : undefined}
        role={isSheet ? 'dialog' : undefined}
        aria-modal={isSheet || undefined}
        aria-label={isSheet ? 'Secure checkout' : undefined}
        className={isSheet
          ? 'relative flex max-h-[94dvh] w-full max-w-3xl flex-col overflow-hidden rounded-t-[2rem] border border-b-0 border-white/15 bg-[#111113]/95 shadow-[0_-24px_80px_rgba(0,0,0,0.55)] backdrop-blur-3xl'
          : 'flex min-h-screen flex-col bg-[#0A0A0A]'}
      >
      {/* Simple Header */}
      <header className={isSheet
        ? 'sticky top-0 z-50 border-b border-white/10 bg-[#111113]/90 px-4 pb-3 pt-2 backdrop-blur-2xl'
        : 'sticky top-0 z-50 grid grid-cols-[1fr_auto] items-center gap-x-3 gap-y-2 border-b border-white/10 bg-[#141414] px-4 py-3 sm:grid-cols-[1fr_auto_1fr] sm:px-6 sm:py-4'}>
        {isSheet && <div className="mx-auto mb-2 h-1.5 w-10 rounded-full bg-white/20" aria-hidden="true" />}
        <div className={isSheet ? 'grid grid-cols-[1fr_auto_1fr] items-center' : 'contents'}>
        <button type="button" autoFocus={isSheet} className="flex items-center gap-2 justify-self-start" onClick={closeCheckout}>
          {isSheet ? <X className="h-5 w-5 text-white/65" /> : <ChevronLeft className="w-5 h-5 text-gray-400" />}
          <span className="font-bold text-gray-300">{isSheet ? 'Close' : 'Back'}</span>
        </button>
        <div className="justify-self-center text-base font-black tracking-[-0.02em] text-white sm:text-xl">{isSheet ? 'Checkout' : 'WERSEE'}</div>
        {isSheet ? <div /> : <LocaleCurrencyPicker className="col-span-2 w-full justify-end sm:col-span-1 sm:justify-self-end" />}
        </div>
      </header>

      <div className={isSheet
        ? 'w-full flex-1 overflow-y-auto overscroll-contain px-4 pb-[calc(1.5rem+env(safe-area-inset-bottom))] pt-5 sm:px-6'
        : 'flex-1 max-w-5xl w-full mx-auto px-4 py-12'}>
        {/* Step Progress Bar */}
        <div className={isSheet ? 'mb-6' : 'mb-12'}>
          {isSheet ? (
            <div className="rounded-2xl border border-white/10 bg-white/[0.045] px-4 py-3">
              <div className="mb-2 flex items-center justify-between text-xs font-bold">
                <span className="text-white">{steps[step - 1]?.name}</span>
                <span className="text-white/35">Step {step} of {steps.length}</span>
              </div>
              <div className="grid grid-cols-4 gap-1.5" aria-label={`Checkout step ${step} of ${steps.length}`}>
                {steps.map(item => <span key={item.id} className={`h-1 rounded-full transition-colors duration-500 ${step >= item.id ? 'bg-white' : 'bg-white/10'}`} />)}
              </div>
            </div>
          ) : (
          <div className="flex items-center justify-between max-w-2xl mx-auto relative">
            {steps.map((s, idx) => (
              <div key={s.id} className="flex flex-col items-center relative z-10">
                <div 
                  className={`w-12 h-12 rounded-full flex items-center justify-center transition-all duration-500 ${
                    step >= s.id ? 'bg-white text-black shadow-lg shadow-white/10' : 'bg-[#1A1A1A] text-gray-500'
                  }`}
                >
                  <s.icon className="w-5 h-5" />
                </div>
                <span className={`mt-3 text-sm font-bold ${step >= s.id ? 'text-white' : 'text-gray-500'}`}>
                  {s.name}
                </span>
                {idx < steps.length - 1 && (
                  <div className="absolute top-6 left-12 w-[calc(100vw/3)] max-w-[180px] h-[2px] bg-[#1A1A1A] -z-10">
                    <div 
                      className="h-full bg-white transition-all duration-500" 
                      style={{ width: step > s.id ? '100%' : '0%' }}
                    />
                  </div>
                )}
              </div>
            ))}
          </div>
          )}
        </div>

        <div className="grid grid-cols-1 gap-12 items-start">
          <AnimatePresence mode="wait">
            {step === 1 && (
              <motion.div
                key="step1"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                className="space-y-8"
              >
                <div className="bg-[#141414] p-8 rounded-[2.5rem] border border-white/5 shadow-sm">
                  <p className="text-xs font-black uppercase tracking-[0.22em] text-white/35">Secure checkout</p>
                  <h2 className="mt-2 text-3xl font-black tracking-tight mb-2 text-white">Build your order</h2>
                  <p className="mb-7 text-sm leading-6 text-white/45">Confirm the product, plan and price before adding your delivery details.</p>
                  
                  {/* Product Summary */}
                  <div className="flex gap-6 p-6 bg-[#1A1A1A] rounded-[2rem] border border-white/5 mb-8">
                    <div className="w-24 h-24 bg-[#252525] rounded-2xl overflow-hidden shadow-sm shrink-0">
                      {listing.images?.[0] ? (
                        <img 
                          src={listing.images[0]} 
                          alt={listing.title} 
                          className="w-full h-full object-cover"
                          referrerPolicy="no-referrer"
                        />
                      ) : (
                        <div className="flex h-full w-full items-center justify-center">
                          <ShoppingBag className="h-8 w-8 text-white/25" />
                        </div>
                      )}
                    </div>
                    <div className="flex-1">
                      <h3 className="font-bold text-xl text-white">{listing.title}</h3>
                      <p className="text-gray-400 capitalize">{listing.type}</p>
                      {listing.type === 'asset_3d' && selected3DLicense && (
                        <p className="mt-2 inline-flex rounded-md border border-white/10 bg-white/[0.04] px-2.5 py-1 text-xs font-semibold text-gray-300">
                          {selected3DLicense.name}
                        </p>
                      )}
                    </div>
                  </div>

                  {/* Plans Selection */}
                  {listing.plans && listing.plans.length > 0 && (
                    <div className="mb-8">
                      <h3 className="text-lg font-bold mb-4 text-white">Choose a Plan</h3>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        {listing.plans.map((plan: any, idx: number) => (
                          <button
                            key={idx}
                            onClick={() => setSelectedPlan(idx)}
                            className={`p-4 rounded-2xl border-2 text-left transition-all ${
                              selectedPlan === idx ? 'border-white bg-white/5' : 'border-white/5 hover:border-white/10'
                            }`}
                          >
                            <div className="flex justify-between items-center mb-2">
                              <span className="font-bold text-white">{plan.name}</span>
                              {selectedPlan === idx && <CheckCircle2 className="w-5 h-5 text-white" />}
                            </div>
                            <LocalizedPrice
                              amount={plan.price}
                              baseCurrency={plan.currency || listing.currency || listing.base_currency || 'EUR'}
                              className="text-2xl font-black mb-2 text-white"
                              showOriginal={false}
                            />
                            <ul className="space-y-1">
                              {plan.features?.map((f: string, i: number) => (
                                <li key={i} className="text-sm text-gray-400 flex items-center gap-2">
                                  <div className="w-1.5 h-1.5 rounded-full bg-white/20" />
                                  {f}
                                </li>
                              ))}
                            </ul>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* Price Display if no plans */}
                  {(!listing.plans || listing.plans.length === 0) && (
                    <div className="mb-8 flex justify-between items-center p-6 bg-[#1A1A1A] rounded-2xl border border-white/5">
                      <div><span className="font-bold text-lg text-white">Total Price</span>{checkoutPricing.isOnSale && <p className="mt-1 text-xs font-bold text-emerald-400">You save {checkoutPricing.discountPercent}%</p>}</div>
                  <div className="text-right">
                    {priceAvailable ? (
                      <>
                        {checkoutPricing.isOnSale && <LocalizedPrice amount={checkoutPricing.originalPrice} baseCurrency={baseCurrency} className="mb-1 block text-sm font-bold text-gray-500 line-through" />}
                        <LocalizedPrice amount={price} baseCurrency={baseCurrency} className="text-3xl font-black text-white" />
                      </>
                    ) : (
                      <span className="text-sm font-bold text-amber-300">Price unavailable</span>
                    )}
                  </div>
                    </div>
                  )}

                  <button
                    type="button"
                    onClick={() => setStep(2)}
                    disabled={!priceAvailable}
                    className="mt-8 flex w-full items-center justify-center gap-2 rounded-full bg-white py-4 text-base font-black text-black transition hover:bg-indigo-100 disabled:opacity-40"
                  >
                    Continue to details <ArrowRight className="h-5 w-5" />
                  </button>
                </div>
              </motion.div>
            )}

            {step === 2 && (
              <motion.div
                key="step2"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                className="space-y-8"
              >
                <div className="rounded-[2.5rem] border border-white/5 bg-[#141414] p-6 shadow-sm sm:p-8">
                  <div className="mb-7 flex items-start justify-between gap-4">
                    <div>
                      <p className="text-xs font-black uppercase tracking-[0.22em] text-indigo-300">Customer details</p>
                      <h2 className="mt-2 text-3xl font-black tracking-tight text-white">Delivery and consent</h2>
                      <p className="mt-2 text-sm leading-6 text-white/45">Tell us where to send your receipt and confirm the choices that apply to this purchase.</p>
                    </div>
                    <button type="button" onClick={() => setStep(1)} className="flex shrink-0 items-center gap-1 rounded-full border border-white/10 px-3 py-2 text-xs font-bold text-white/50 hover:bg-white/5 hover:text-white"><ChevronLeft className="h-4 w-4" /> Order</button>
                  </div>

                  {/* Contact Info */}
                  <div className="space-y-6">
                    {!user ? (
                      <div>
                        <label className="block text-sm font-bold text-gray-300 mb-2">Email Address</label>
                        <div className="relative">
                          <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500" />
                          <input 
                            type="email" 
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="you@example.com"
                            className="w-full pl-12 pr-4 py-4 rounded-2xl border border-white/10 bg-[#1A1A1A] text-white outline-none focus:border-white focus:ring-4 focus:ring-white/5 transition-all placeholder-gray-600"
                          />
                        </div>
                        <p className="mt-3 text-xs leading-5 text-gray-500">Your receipt and access instructions are sent to this address. Account creation is always a separate choice.</p>
                      </div>
                    ) : (
                      <div className="p-4 bg-[#1A1A1A] rounded-2xl border border-white/5 flex items-center gap-4">
                        <div className="w-12 h-12 bg-white text-black rounded-full flex items-center justify-center font-bold">
                          {user.email?.[0].toUpperCase()}
                        </div>
                        <div>
                          <span className="text-sm text-gray-500 block">Logged in as</span>
                          <span className="font-bold text-white">{user.email}</span>
                        </div>
                      </div>
                    )}
                  </div>

                  {isDigitalProduct && (
                    <fieldset className="mt-6 rounded-2xl border border-blue-400/20 bg-blue-400/[0.08] p-4 sm:p-5">
                      <legend className="px-1 text-sm font-black text-blue-100">Digital delivery choice</legend>
                      <p className="mb-4 text-xs leading-5 text-blue-100/65">
                        These choices are never preselected. They apply only if you want access to start immediately.
                      </p>
                      <div className="space-y-3">
                        <label className="flex cursor-pointer items-start gap-3 rounded-xl border border-white/10 bg-black/20 p-3.5">
                          <input
                            type="checkbox"
                            checked={immediateDeliveryRequested}
                            onChange={(event) => setImmediateDeliveryRequested(event.target.checked)}
                            className="mt-0.5 h-5 w-5 shrink-0 accent-blue-400"
                          />
                          <span className="text-sm leading-5 text-white/85">I request immediate access to this digital content.</span>
                        </label>
                        <label className="flex cursor-pointer items-start gap-3 rounded-xl border border-white/10 bg-black/20 p-3.5">
                          <input
                            type="checkbox"
                            checked={withdrawalEffectAcknowledged}
                            onChange={(event) => setWithdrawalEffectAcknowledged(event.target.checked)}
                            className="mt-0.5 h-5 w-5 shrink-0 accent-blue-400"
                          />
                          <span className="text-sm leading-5 text-white/85">I understand that once delivery begins, my statutory withdrawal right may be affected or lost where applicable.</span>
                        </label>
                      </div>
                      <details className="mt-3 text-xs text-blue-100/65">
                        <summary className="cursor-pointer font-bold text-blue-100">Why is this needed?</summary>
                        <p className="mt-2 leading-5">Digital access can begin before a normal withdrawal period ends. Wersee stores your exact choice, its wording, the product and the applicable policy version.</p>
                      </details>
                    </fieldset>
                  )}

                  <div className="mt-6 rounded-2xl border border-white/10 bg-white/[0.025] p-4 text-xs leading-5 text-white/55">
                    <div className="flex items-start gap-2">
                      <Info className="mt-0.5 h-4 w-4 shrink-0 text-white/70" />
                      <div>
                        <p className="font-bold text-white/80">Purchase details</p>
                        <p className="mt-1">
                          {sellerTrace?.trader_status === 'business'
                            ? 'Sold by a business seller.'
                            : sellerTrace?.trader_status === 'private'
                              ? 'Sold by a private seller.'
                              : 'Seller classification is not available.'}{' '}
                          {isSubscription
                            ? listing.billing_interval || listing.metadata?.subscription_interval
                              ? `Recurring ${listing.billing_interval || listing.metadata.subscription_interval} billing.`
                              : 'Recurring billing; the cadence is shown in Stripe before confirmation.'
                            : 'One-time purchase.'}
                        </p>
                        <p>Taxes calculated at checkout. {isPhysicalProduct ? 'Any shipping charge is shown before payment confirmation.' : ''}</p>
                      </div>
                    </div>
                  </div>

                  {isPhysicalProduct && (
                    <div className="mt-4 rounded-2xl border border-emerald-400/20 bg-emerald-400/[0.06] p-4 text-xs leading-5 text-white/65">
                      <div className="flex items-start gap-2">
                        <ShieldCheck className="mt-0.5 h-4 w-4 shrink-0 text-emerald-300" />
                        <div>
                          <p className="font-bold text-white/85">Protected physical delivery</p>
                          <p className="mt-1">Stripe processes your payment. Wersee delays the seller transfer in a Payment Reserve until you confirm the in-package QR or a problem is reviewed. This is not an escrow or bank account.</p>
                          {!user && <p className="mt-2 text-amber-200">Physical checkout requires an account so only the linked buyer can confirm delivery. <Link to={`/signin?redirect=${encodeURIComponent(window.location.pathname + window.location.search)}`} className="font-bold underline">Sign in to continue</Link>.</p>}
                        </div>
                      </div>
                    </div>
                  )}

                  {complianceDecision && complianceDecision.disclosures?.length > 0 && (
                    <div className="mt-4 space-y-2" aria-label="Checkout disclosures">
                      {complianceDecision.disclosures.map((disclosure) => (
                        <div key={disclosure.code} className="rounded-xl border border-white/10 bg-white/[0.025] px-4 py-3 text-xs text-white/60">
                          <span className="font-bold text-white/80">{disclosure.title}.</span> {disclosure.explanation}
                        </div>
                      ))}
                    </div>
                  )}

                  {paymentError && (
                    <div role="alert" className="mt-6 flex items-start gap-3 rounded-2xl border border-red-400/20 bg-red-400/10 p-4 text-sm text-red-100">
                      <AlertCircle className="mt-0.5 h-5 w-5 shrink-0 text-red-300" />
                      <div>
                        <p className="font-bold">Payment could not start</p>
                        <p className="mt-1 text-red-100/70">{paymentError}</p>
                      </div>
                    </div>
                  )}

                  <button 
                    onClick={handleContinueToPayment}
                    disabled={!priceAvailable || processing || (!user && (isPhysicalProduct || !EMAIL_PATTERN.test(email.trim()))) || (isDigitalProduct && (!immediateDeliveryRequested || !withdrawalEffectAcknowledged)) || (!isFree && (stripeConfigLoading || paymentReadiness !== 'ready'))}
                    className="w-full mt-8 py-4 bg-white text-black rounded-full font-bold text-lg hover:bg-gray-200 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
                  >
                    {processing || stripeConfigLoading && !isFree ? (
                      <div className="w-6 h-6 border-3 border-black border-t-transparent rounded-full animate-spin"></div>
                    ) : (
                      <>
                        {isFree
                          ? (user ? 'Get access' : 'Sign in to get access')
                          : paymentReadiness === 'checking'
                            ? 'Checking payment availability'
                            : paymentReadiness === 'unavailable'
                              ? 'Payment unavailable'
                              : 'Continue to secure payment'} <ArrowRight className="w-5 h-5" />
                      </>
                    )}
                  </button>
                </div>
              </motion.div>
            )}

            {step === 3 && clientSecret && !isFree && (
              <motion.div
                key="step3"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                className="space-y-8"
              >
                <CheckoutProvider
                  stripe={stripePromise}
                  options={{
                    clientSecret,
                    elementsOptions: {
                      loader: 'auto',
                      appearance: {
                        theme: 'night',
                        variables: {
                          colorPrimary: '#818CF8',
                          colorBackground: '#0B0B0D',
                          colorText: '#FFFFFF',
                          colorDanger: '#FB7185',
                          fontFamily: 'Inter, system-ui, sans-serif',
                          borderRadius: '14px',
                          spacingUnit: '4px',
                        },
                        rules: {
                          '.Input': { border: '1px solid rgba(255,255,255,0.12)', boxShadow: 'none' },
                          '.Input:focus': { border: '1px solid #A5B4FC', boxShadow: '0 0 0 3px rgba(129,140,248,0.15)' },
                          '.Tab': { border: '1px solid rgba(255,255,255,0.1)' },
                          '.Tab--selected': { border: '1px solid #A5B4FC', boxShadow: '0 0 0 2px rgba(129,140,248,0.12)' },
                        },
                      },
                    },
                  }}
                >
                  <StorePaymentForm
                    listing={listing}
                    email={email || user?.email || ''}
                    isPhysical={isPhysicalProduct}
                    onBack={() => setStep(2)}
                    onComplete={sessionId => void handlePaymentComplete(sessionId)}
                  />
                </CheckoutProvider>
              </motion.div>
            )}

            {step === 4 && paymentResult && confirmation && (
              <motion.section
                key={`step4-${paymentResult.view}-${paymentResult.verifying}`}
                initial={reduceMotion ? false : { opacity: 0, scale: 0.96, y: 18 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.98 }}
                className="mx-auto w-full max-w-xl py-3 text-center sm:py-8"
                aria-live="polite"
              >
                <motion.div
                  initial={reduceMotion ? false : { scale: 0.75, rotate: -8 }}
                  animate={{ scale: 1, rotate: 0 }}
                  transition={reduceMotion ? { duration: 0 } : { type: 'spring', stiffness: 330, damping: 22, delay: 0.08 }}
                  className={`mx-auto flex h-20 w-20 items-center justify-center rounded-[1.75rem] border ${confirmation.surface}`}
                >
                  {paymentResult.verifying
                    ? <Loader2 className={`h-9 w-9 animate-spin ${confirmation.tone}`} />
                    : <ConfirmationIcon className={`h-9 w-9 ${confirmation.tone}`} />}
                </motion.div>
                <p className={`mt-6 text-[11px] font-black uppercase tracking-[0.24em] ${confirmation.tone}`}>
                  {paymentResult.verifying ? 'Verifying with your provider' : confirmation.eyebrow}
                </p>
                <h2 className="mt-3 text-3xl font-black tracking-[-0.04em] text-white sm:text-5xl">
                  {paymentResult.verifying ? 'One moment.' : confirmation.title}
                </h2>
                <p className="mx-auto mt-4 max-w-md text-sm leading-6 text-white/50 sm:text-base">
                  {paymentResult.verifying
                    ? 'Wersee is checking the latest payment status. Keep this sheet open.'
                    : confirmation.description}
                </p>

                {!paymentResult.verifying && (
                  <>
                    {paymentResult.reference && (
                      <div className="mt-6 rounded-2xl border border-white/10 bg-white/[0.035] px-4 py-3 text-left">
                        <p className="text-[10px] font-black uppercase tracking-[0.2em] text-white/30">Reference</p>
                        <p className="mt-1 truncate font-mono text-xs text-white/60">{paymentResult.reference}</p>
                      </div>
                    )}
                    <div className="mt-7 grid gap-3 sm:grid-cols-2">
                      {(paymentResult.view === 'failed' || paymentResult.view === 'cancelled') ? (
                        <button type="button" onClick={() => { setPaymentResult(null); setStep(3); }} className="flex min-h-14 items-center justify-center gap-2 rounded-2xl bg-white px-5 text-sm font-black text-black">
                          <RefreshCw className="h-4 w-4" /> Try another method
                        </button>
                      ) : (
                        <button type="button" onClick={closeCheckout} className="flex min-h-14 items-center justify-center gap-2 rounded-2xl bg-white px-5 text-sm font-black text-black">
                          <CheckCircle2 className="h-4 w-4" /> Done
                        </button>
                      )}
                      <a href="https://billing.wersee.com" className="flex min-h-14 items-center justify-center gap-2 rounded-2xl border border-white/10 bg-white/[0.045] px-5 text-sm font-bold text-white">
                        <ReceiptText className="h-4 w-4" /> Open Billing
                      </a>
                    </div>
                  </>
                )}
              </motion.section>
            )}
          </AnimatePresence>
        </div>
      </div>
      </motion.div>
    </div>
  );
};
